168	func TestRenderExperimentalCommands_MultiByteInvocationAligns(t *testing.T) {
169		t.Parallel()
170	
171		// "entire ▶▶" is 9 runes but 13 bytes (each ▶ is 3 bytes). The longest
172		// invocation below is 12 runes, so the column width is 12. With byte-based
173		// padding, len("entire ▶▶") == 13 >= 12 would skip padding and misalign the
174		// row; rune-based padding correctly adds 3 spaces.
175		commands := []experimentalCommandInfo{
176			{Name: "long", Invocation: "entire aaaaa", Summary: "first"},
177			{Name: "multibyte", Invocation: "entire ▶▶", Summary: "second"},
178		}
179	
180		if got := len("entire ▶▶"); got < 12 {
181			t.Fatalf("test precondition broken: byte length %d should exceed column width 12", got)
182		}
183	
184		cols := summaryColumns(t, commands)
185		if cols[0] != cols[1] {
186			t.Fatalf("multi-byte invocation summary misaligned: %v", cols)
187		}
