181	func runAttributionBlame(ctx context.Context, w io.Writer, file string, opts attributionBlameOptions) error {
182		var lineRange *attributionLineRange
183		if opts.LineFlag != "" {
184			parsed, err := parseAttributionLineRange(opts.LineFlag)
