208	func runAttributionWhy(ctx context.Context, w io.Writer, target string, jsonOutput bool) error {
209		file, line, hasLine, err := parseAttributionWhyTarget(target)
210		if err != nil {
211			return err
212		}
213	
214		result, err := resolveFileAttribution(ctx, file, false)
215		if err != nil {
216			return err
217		}
218	
219		if !hasLine {
220			if jsonOutput {
221				return writeJSON(w, result)
222			}
223			renderAttributionFileWhy(w, result)
224			return nil
225		}
226	
227		var selected *attributionLine
228		for i := range result.Lines {
229			if result.Lines[i].LineNumber == line {
230				selected = &result.Lines[i]
231				break
232			}
233		}
234		if selected == nil {
235			return fmt.Errorf("line %d is outside %s", line, result.File)
236		}
237		if selected.MetadataMissing && selected.CheckpointID != "" {
238			if err := enrichAttributionLineWithFetch(ctx, result.File, selected, result.Checkpoints); err != nil {
239				// Remote metadata enrichment is best-effort; the trailer-level
240				// explanation is still useful and should remain available.
241				selected.MetadataMissing = true
242			}
243		}
