261	func resolveFileAttribution(ctx context.Context, file string, fetchOnMiss bool) (*fileAttributionResult, error) {
262		repoRoot, err := paths.WorktreeRoot(ctx)
263		if err != nil {
264			return nil, errors.New("not a git repository")
265		}
266		relFile, err := normalizeAttributionPath(repoRoot, file)
267		if err != nil {
268			return nil, err
269		}
270	
271		rawLines, err := runGitBlame(ctx, repoRoot, relFile)
272		if err != nil {
273			return nil, err
274		}
275	
276		resolver, err := newAttributionResolver(ctx, fetchOnMiss)
277		if err != nil {
278			return nil, err
279		}
280		defer resolver.Close()
281	
282		result := &fileAttributionResult{
283			File:        relFile,
284			Lines:       make([]attributionLine, 0, len(rawLines)),
285			Checkpoints: make(map[string]attributionCheckpointContext),
286		}
287		for _, raw := range rawLines {
288			line := resolver.resolveLine(raw, relFile)
289			result.Lines = append(result.Lines, line)
290			for _, candidate := range line.Candidates {
291				if candidate.MetadataMissing {
292					result.Checkpoints[candidate.CheckpointID] = attributionCheckpointContext{
293						CheckpointID:    candidate.CheckpointID,
294						MetadataMissing: true,
295					}
296					continue
297				}
298				if checkpointCtx, ok := resolver.checkpointCache[candidate.CheckpointID]; ok {
299					result.Checkpoints[candidate.CheckpointID] = checkpointCtx
300				}
301			}
302		}
303		result.Summary = summarizeAttributionLines(result.Lines)
304		return result, nil
305	}
