311		}
312	
313		store := checkpoint.NewGitStore(repo)
314		store.SetBlobFetcher(FetchBlobsByHash)
315	
316		return &attributionResolver{
317			ctx:             ctx,
318			repo:            repo,
319			store:           store,
320			fetchOnMiss:     fetchOnMiss,
321			commitCache:     make(map[string]*object.Commit),
322			checkpointCache: make(map[string]attributionCheckpointContext),
323		}, nil
