332	func (r *attributionResolver) resolveLine(raw rawBlameLine, file string) attributionLine {
333		line := attributionLine{
334			LineNumber: raw.LineNumber,
335			CommitSHA:  raw.CommitSHA,
336			Author:     raw.Author,
337			AuthorTime: raw.AuthorTime,
338			Content:    raw.Content,
339		}
340		if raw.CommitSHA != "" && !isZeroCommit(raw.CommitSHA) {
341			line.ShortCommitSHA = shortSHA(raw.CommitSHA)
342		}
343	
344		if isZeroCommit(raw.CommitSHA) {
345			line.Authorship = attributionUncommitted
346			line.Tag = attributionTag(line.Authorship)
347			return line
348		}
349	
350		commit, err := r.commit(raw.CommitSHA)
351		if err != nil {
352			line.Authorship = attributionHuman
353			line.Tag = attributionTag(line.Authorship)
354			return line
355		}
356	
357		cpIDs := trailers.ParseAllCheckpoints(commit.Message)
358		if len(cpIDs) == 0 {
359			line.Authorship = attributionHuman
360			line.Tag = attributionTag(line.Authorship)
361			return line
362		}
363	
364		line.Authorship = attributionAI
365		var candidates []attributionCandidate
366		for _, cpID := range cpIDs {
367			candidates = append(candidates, candidateFromContext(r.checkpointContext(cpID, file)))
368		}
369	
370		preferred := preferredAttributionCandidate(candidates, file)
371		applyPreferredToLine(&line, preferred)
372		if preferred != nil && preferred.Mixed {
373			line.Authorship = attributionMixed
374		}
375		if len(candidates) > 0 {
376			line.Candidates = candidates
377		}
378	
379		line.Tag = attributionTag(line.Authorship)
380		return line
381	}
