383	func (r *attributionResolver) commit(sha string) (*object.Commit, error) {
384		if commit, ok := r.commitCache[sha]; ok {
385			return commit, nil
386		}
387		commit, err := r.repo.CommitObject(plumbing.NewHash(sha))
388		if err != nil {
389			return nil, err //nolint:wrapcheck // caller treats as missing attribution
390		}
391		r.commitCache[sha] = commit
392		return commit, nil
393	}
