406	func (r *attributionResolver) readCheckpointContext(cpID id.CheckpointID, file string) attributionCheckpointContext {
407		ctx := attributionCheckpointContext{CheckpointID: cpID.String()}
408		summary, err := checkpoint.ReadCommittedCheckpoint(r.ctx, r.store, cpID)
409		if err != nil && r.fetchOnMiss {
410			if fetched, fetchErr := r.fetchCheckpointContext(cpID, file); fetchErr == nil {
411				return fetched
412			}
413		}
414		if err != nil {
415			ctx.MetadataMissing = true
416			return ctx
417		}
418	
419		ctx.FilesTouched = normalizePathSlice(summary.FilesTouched)
420		if attributionIsMixed(summary.CombinedAttribution) {
421			ctx.Mixed = true
422		}
423	
424		selected := checkpointSessionForFile{}
425		var fallback checkpointSessionForFile
426		for i := range summary.Sessions {
427			sessionCtx, readErr := r.readSessionForCheckpoint(cpID, i)
428			if readErr != nil {
429				continue
430			}
431			if attributionIsMixed(sessionCtx.Attribution) {
432				ctx.Mixed = true
433			}
434			if fallback.SessionID == "" {
435				fallback = sessionCtx
436			}
437			if selected.SessionID == "" && pathsContainFile(sessionCtx.FilesTouched, file) {
438				selected = sessionCtx
439			}
440		}
441	
442		if selected.SessionID == "" {
443			selected = fallback
444		}
445		ctx.SessionID = selected.SessionID
446		ctx.Agent = selected.Agent
447		ctx.Model = selected.Model
448		ctx.Prompt = selected.Prompt
449		ctx.Intent = selected.Intent
450		if len(selected.FilesTouched) > 0 {
451			ctx.FilesTouched = selected.FilesTouched
452		}
453		if len(ctx.FilesTouched) == 0 {
454			ctx.FilesTouched = normalizePathSlice(summary.FilesTouched)
455		}
456		return ctx
457	}
