459	func enrichAttributionLineWithFetch(ctx context.Context, file string, line *attributionLine, checkpoints map[string]attributionCheckpointContext) error {
460		if line == nil || len(line.Candidates) == 0 {
461			return nil
462		}
463		resolver, err := newAttributionResolver(ctx, true)
464		if err != nil {
465			return err
466		}
467		defer resolver.Close()
468	
469		candidates := make([]attributionCandidate, 0, len(line.Candidates))
470		authorship := attributionAI
471		for _, candidate := range line.Candidates {
472			cpID, idErr := id.NewCheckpointID(candidate.CheckpointID)
473			if idErr != nil {
474				candidates = append(candidates, candidate)
475				continue
476			}
477			cpCtx := resolver.checkpointContext(cpID, file)
478			checkpoints[cpCtx.CheckpointID] = cpCtx
479			if cpCtx.Mixed {
480				authorship = attributionMixed
481			}
482			candidates = append(candidates, candidateFromContext(cpCtx))
483		}
484		applyPreferredToLine(line, preferredAttributionCandidate(candidates, file))
485		line.Candidates = candidates
486		line.Authorship = authorship
487		line.Tag = attributionTag(authorship)
488		return nil
489	}
