491	func (r *attributionResolver) fetchCheckpointContext(cpID id.CheckpointID, file string) (attributionCheckpointContext, error) {
492		lookup, err := newExplainCheckpointLookup(r.ctx)
493		if err != nil {
494			return attributionCheckpointContext{}, err
495		}
496		defer lookup.Close()
497	
498		matches, fresh := matchCheckpointPrefixWithRemoteFallback(r.ctx, io.Discard, lookup, cpID.String())
499		if fresh != lookup {
500			defer fresh.Close()
501		}
502		if len(matches) != 1 {
503			return attributionCheckpointContext{}, checkpoint.ErrCheckpointNotFound
504		}
505	
506		oldStore := r.store
507		oldFetchOnMiss := r.fetchOnMiss
508		r.store = fresh.store
509		r.fetchOnMiss = false
510		ctx := r.readCheckpointContext(cpID, file)
511		r.store = oldStore
512		r.fetchOnMiss = oldFetchOnMiss
513		return ctx, nil
514	}
