554	func runGitBlame(ctx context.Context, repoRoot, file string) ([]rawBlameLine, error) {
555		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "blame", "--line-porcelain", "--", file)
556		var stderr bytes.Buffer
557		cmd.Stderr = &stderr
558		out, err := cmd.Output()
559		if err != nil {
560			msg := strings.TrimSpace(stderr.String())
561			if msg != "" {
562				return nil, fmt.Errorf("git blame --line-porcelain %s: %w (stderr: %s)", file, err, msg)
563			}
564			return nil, fmt.Errorf("git blame --line-porcelain %s: %w", file, err)
565		}
566		return parseBlamePorcelain(string(out))
567	}
568	
569	var blameHeaderRe = regexp.MustCompile(`^([0-9a-f]{40}|[0-9a-f]{64})\s+\d+\s+(\d+)(?:\s+\d+)?$`)
570	
571	func parseBlamePorcelain(output string) ([]rawBlameLine, error) {
572		scanner := bufio.NewScanner(strings.NewReader(output))
573		scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
574	
575		var current *rawBlameLine
576		var lines []rawBlameLine
577		for scanner.Scan() {
578			line := scanner.Text()
579			if match := blameHeaderRe.FindStringSubmatch(line); match != nil {
580				lineNumber, err := strconv.Atoi(match[2])
581				if err != nil {
582					return nil, fmt.Errorf("parse blame line number %q: %w", match[2], err)
583				}
584				current = &rawBlameLine{CommitSHA: match[1], LineNumber: lineNumber}
585				continue
586			}
587			if current == nil {
588				continue
589			}
590			switch {
591			case strings.HasPrefix(line, "author "):
592				current.Author = strings.TrimPrefix(line, "author ")
593			case strings.HasPrefix(line, "author-time "):
594				seconds, err := strconv.ParseInt(strings.TrimPrefix(line, "author-time "), 10, 64)
595				if err == nil {
596					t := time.Unix(seconds, 0).UTC()
597					current.AuthorTime = &t
598				}
599			case strings.HasPrefix(line, "\t"):
600				current.Content = strings.TrimPrefix(line, "\t")
601				lines = append(lines, *current)
602				current = nil
603			}
604		}
605		if err := scanner.Err(); err != nil {
606			return nil, fmt.Errorf("scan git blame output: %w", err)
607		}
608		return lines, nil
609	}
