611	func parseAttributionLineRange(input string) (*attributionLineRange, error) {
612		parts := strings.Split(input, "-")
613		if len(parts) > 2 || parts[0] == "" {
614			return nil, fmt.Errorf("invalid line range %q: use N or N-M", input)
615		}
616		start, err := strconv.Atoi(parts[0])
617		if err != nil || start < 1 {
618			return nil, fmt.Errorf("invalid line range %q: start must be a positive integer", input)
619		}
620		end := start
621		if len(parts) == 2 {
622			if parts[1] == "" {
623				return nil, fmt.Errorf("invalid line range %q: end must be a positive integer", input)
624			}
625			end, err = strconv.Atoi(parts[1])
626			if err != nil || end < 1 {
627				return nil, fmt.Errorf("invalid line range %q: end must be a positive integer", input)
628			}
629		}
630		if end < start {
631			return nil, fmt.Errorf("invalid line range %q: end must be >= start", input)
632		}
633		return &attributionLineRange{Start: start, End: end}, nil
634	}
635	
636	func parseAttributionWhyTarget(input string) (file string, line int, hasLine bool, err error) {
637		colon := strings.LastIndex(input, ":")
638		if colon == -1 || colon == len(input)-1 {
639			return input, 0, false, nil
640		}
641		if volume := filepath.VolumeName(input); volume != "" && colon < len(volume) {
642			return input, 0, false, nil
643		}
644		linePart := input[colon+1:]
645		parsed, parseErr := strconv.Atoi(linePart)
646		if parseErr != nil || parsed < 1 {
647			return "", 0, false, fmt.Errorf("invalid line target %q: use file:line", input)
648		}
649		return input[:colon], parsed, true, nil
650	}
