652	func normalizeAttributionPath(repoRoot, file string) (string, error) {
653		path := file
654		if !filepath.IsAbs(path) {
655			abs, err := filepath.Abs(path)
656			if err != nil {
657				return "", fmt.Errorf("resolve path %s: %w", file, err)
658			}
659			path = abs
660		}
661		canonicalRepoRoot := repoRoot
662		if resolved, err := filepath.EvalSymlinks(repoRoot); err == nil {
663			canonicalRepoRoot = resolved
664		}
665		canonicalPath := path
666		if resolved, err := filepath.EvalSymlinks(path); err == nil {
667			canonicalPath = resolved
668		}
669		rel, err := filepath.Rel(canonicalRepoRoot, canonicalPath)
670		if err != nil {
671			return "", fmt.Errorf("resolve path %s relative to repository: %w", file, err)
672		}
673		if rel == "." || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) || rel == ".." {
674			return "", fmt.Errorf("%s is outside the repository", file)
675		}
676		return filepath.ToSlash(rel), nil
677	}
