679	func filterAttributionLines(lines []attributionLine, lineRange attributionLineRange) []attributionLine {
680		filtered := make([]attributionLine, 0, len(lines))
681		for _, line := range lines {
682			if line.LineNumber >= lineRange.Start && line.LineNumber <= lineRange.End {
683				filtered = append(filtered, line)
684			}
685		}
686		return filtered
687	}
