689	func checkpointContextsForLines(lines []attributionLine, contexts map[string]attributionCheckpointContext) map[string]attributionCheckpointContext {
690		if len(lines) == 0 || len(contexts) == 0 {
691			return nil
692		}
693		pruned := make(map[string]attributionCheckpointContext)
694		for _, line := range lines {
695			for _, candidate := range line.Candidates {
696				if ctx, ok := contexts[candidate.CheckpointID]; ok {
697					pruned[candidate.CheckpointID] = ctx
698				}
699			}
700			if line.CheckpointID != "" {
701				if ctx, ok := contexts[line.CheckpointID]; ok {
702					pruned[line.CheckpointID] = ctx
703				}
704			}
705		}
706		if len(pruned) == 0 {
707			return nil
708		}
709		return pruned
710	}
