712	func summarizeAttributionLines(lines []attributionLine) attributionSummary {
713		var summary attributionSummary
714		summary.TotalLines = len(lines)
715		for _, line := range lines {
716			switch line.Authorship {
717			case attributionAI:
718				summary.AILines++
719			case attributionHuman:
720				summary.HumanLines++
721			case attributionMixed:
722				summary.MixedLines++
723			case attributionUncommitted:
724				summary.UncommittedLines++
725			}
726		}
727		if summary.TotalLines > 0 {
728			summary.AIPercentage = summary.AILines * 100 / summary.TotalLines
729			summary.HumanPercentage = summary.HumanLines * 100 / summary.TotalLines
730			summary.MixedPercentage = summary.MixedLines * 100 / summary.TotalLines
731		}
732		return summary
733	}
