743	func renderAttributionBlameCompact(w io.Writer, result *fileAttributionResult, lineFlag string) {
744		sty := newStatusStyles(w)
745		fmt.Fprintf(w, "\n  %s\n\n", sty.render(sty.bold, result.File))
746	
747		if len(result.Lines) == 0 {
748			fmt.Fprintln(w, sty.render(sty.dim, "  No lines to display."))
749			return
750		}
751	
752		lineWidth := attributionLineColumnWidth(result.Lines)
753		const agentWidth = 6
754		const authorWidth = 6
755		const checkpointWidth = 12
756		const minContentWidth = 12
757		fixedWidth := 2 + lineWidth + 2 + len("[AI]") + 2 + agentWidth + 2 + authorWidth + 2 + checkpointWidth + 2
758		contentWidth := sty.width - fixedWidth
759		if contentWidth < minContentWidth {
760			contentWidth = minContentWidth
761		}
762		tableWidth := fixedWidth + contentWidth - 2
763	
764		fmt.Fprintf(w, "  %*s  Tag   %-*s  %-*s  %-*s  Content\n", lineWidth, "Line", agentWidth, "Agent", authorWidth, "Author", checkpointWidth, "Checkpoint")
765		fmt.Fprintf(w, "  %s\n", sty.render(sty.dim, strings.Repeat("─", tableWidth)))
766	
767		for _, line := range result.Lines {
768			fmt.Fprintf(w, "  %s  %s  %-*s  %-*s  %-*s  %s\n",
769				sty.render(sty.dim, fmt.Sprintf("%*d", lineWidth, line.LineNumber)),
770				renderAttributionTag(sty, line.Authorship),
771				agentWidth,
772				stringutil.TruncateRunes(compactAttributionAgent(line), agentWidth, ""),
773				authorWidth,
774				stringutil.TruncateRunes(shortAuthorName(line.Author), authorWidth, ""),
775				checkpointWidth,
776				stringutil.TruncateRunes(compactAttributionCheckpoint(line), checkpointWidth, ""),
777				renderAttributionContentCompact(sty, line, contentWidth),
778			)
779		}
780	
781		renderAttributionSummary(w, sty, result.Summary, lineFlag)
782	}
