886				fmt.Fprintf(w, " %s session %s", sty.render(sty.dim, "·"), sty.render(sty.dim, shortSessionID(line.SessionID)))
887			}
888			if line.ShortCommitSHA != "" {
889				fmt.Fprintf(w, " %s commit %s", sty.render(sty.dim, "·"), sty.render(sty.dim, line.ShortCommitSHA))
890			}
891			fmt.Fprintln(w)
892			if line.Prompt != "" {
893				fmt.Fprintf(w, "  %s %q\n", sty.render(sty.bold, "Prompt:"), stringutil.TruncateRunes(stringutil.CollapseWhitespace(line.Prompt), 160, "..."))
894			}
895			if line.Intent != "" && line.Intent != line.Prompt {
896				fmt.Fprintf(w, "  %s %q\n", sty.render(sty.bold, "Intent:"), stringutil.TruncateRunes(stringutil.CollapseWhitespace(line.Intent), 160, "..."))
897			}
898			if line.MetadataMissing {
899				fmt.Fprintf(w, "  %s\n", sty.render(sty.yellow, "Checkpoint metadata was not found locally; showing trailer-level attribution only."))
900			}
901			if len(line.Candidates) > 1 {
902				fmt.Fprintf(w, "\n  %s\n", sty.render(sty.bold, "Candidate checkpoints:"))
903				for _, candidate := range line.Candidates {
904					fmt.Fprintf(w, "  - %s", candidate.CheckpointID)
905					if candidate.SessionID != "" {
906						fmt.Fprintf(w, " session %s", shortSessionID(candidate.SessionID))
907					}
908					if candidate.Agent != "" {
909						fmt.Fprintf(w, " · %s", candidate.Agent)
910					}
911					if candidate.Prompt != "" {
912						fmt.Fprintf(w, " · %q", stringutil.TruncateRunes(stringutil.CollapseWhitespace(candidate.Prompt), 80, "..."))
913					}
914					fmt.Fprintln(w)
915				}
916			}
917			if line.CheckpointID != "" {
918				fmt.Fprintf(w, "\n  %s %s\n\n", sty.render(sty.dim, "Full context:"), sty.render(sty.cyan, "entire checkpoint explain "+line.CheckpointID))
919			} else {
920				fmt.Fprintln(w)
921			}
922		}
923	}
924	
925	func renderAttributionFileWhy(w io.Writer, result *fileAttributionResult) {
926		sty := newStatusStyles(w)
927		summary := result.Summary
928		fmt.Fprintf(w, "\n  %s\n", sty.render(sty.bold, result.File))
929		fmt.Fprintf(w, "  %d lines %s %s %s %s",
930			summary.TotalLines,
931			sty.render(sty.dim, "·"),
932			sty.render(sty.green, fmt.Sprintf("%d%% AI (%d)", summary.AIPercentage, summary.AILines)),
933			sty.render(sty.dim, "·"),
934			fmt.Sprintf("%d%% human (%d)", summary.HumanPercentage, summary.HumanLines),
935		)
936		if summary.MixedLines > 0 {
937			fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), sty.render(sty.yellow, fmt.Sprintf("%d%% mixed (%d)", summary.MixedPercentage, summary.MixedLines)))
938		}
939		fmt.Fprintln(w)
940	
941		counts := checkpointLineCounts(result.Lines)
942		if len(counts) == 0 {
943			fmt.Fprintf(w, "\n  %s\n\n", sty.render(sty.dim, "No Entire checkpoints are linked to this file's current lines."))
944			return
945		}
946	
947		fmt.Fprintf(w, "\n  %s\n", sty.render(sty.bold, "Top checkpoints:"))
948		for _, count := range counts {
949			ctx := result.Checkpoints[count.CheckpointID]
950			fmt.Fprintf(w, "  - %s  %d lines", sty.render(sty.cyan, count.CheckpointID), count.Lines)
951			if ctx.Agent != "" {
952				fmt.Fprintf(w, " %s %s", sty.render(sty.dim, "·"), ctx.Agent)
953			}
954			if ctx.SessionID != "" {
955				fmt.Fprintf(w, " %s session %s", sty.render(sty.dim, "·"), shortSessionID(ctx.SessionID))
956			}
957			if ctx.Prompt != "" {
958				fmt.Fprintf(w, " %s %q", sty.render(sty.dim, "·"), stringutil.TruncateRunes(stringutil.CollapseWhitespace(ctx.Prompt), 90, "..."))
959			}
960			fmt.Fprintln(w)
961		}
962		fmt.Fprintf(w, "\n  %s\n\n", sty.render(sty.dim, "Tip: entire why "+result.File+":<line> shows the prompt behind a specific line."))
963	}
964	
965	type checkpointLineCount struct {
966		CheckpointID string
967		Lines        int
968	}
969	
970	func checkpointLineCounts(lines []attributionLine) []checkpointLineCount {
971		counts := make(map[string]int)
972		for _, line := range lines {
973			if line.CheckpointID != "" {
974				counts[line.CheckpointID]++
975			}
976		}
977		out := make([]checkpointLineCount, 0, len(counts))
978		for cpID, count := range counts {
979			out = append(out, checkpointLineCount{CheckpointID: cpID, Lines: count})
980		}
981		sort.Slice(out, func(i, j int) bool {
982			if out[i].Lines == out[j].Lines {
983				return out[i].CheckpointID < out[j].CheckpointID
984			}
985			return out[i].Lines > out[j].Lines
986		})
987		if len(out) > 5 {
988			out = out[:5]
989		}
990		return out
991	}
992	
993	// renderByAuthorship applies the authorship colour to text. Human and any
994	// unknown authorship render plain.
995	func renderByAuthorship(sty statusStyles, authorship attributionAuthorship, text string) string {
996		switch authorship {
997		case attributionAI:
998			return sty.render(sty.green, text)
999		case attributionMixed:
1000			return sty.render(sty.yellow, text)
1001		case attributionUncommitted:
1002			return sty.render(sty.dim, text)
1003		case attributionHuman:
1004			return text
1005		default:
1006			return text
1007		}
1008	}
1009	
1010	func renderAttributionTag(sty statusStyles, authorship attributionAuthorship) string {
1011		return renderByAuthorship(sty, authorship, attributionTag(authorship))
1012	}
1013	
1014	func renderAttributionContent(sty statusStyles, line attributionLine) string {
1015		return renderByAuthorship(sty, line.Authorship, stringutil.TruncateRunes(line.Content, 120, "..."))
1016	}
1017	
1018	func maxAttributionLineNumber(lines []attributionLine) int {
1019		maxLine := 1
1020		for _, line := range lines {
1021			if line.LineNumber > maxLine {
1022				maxLine = line.LineNumber
1023			}
1024		}
1025		return maxLine
1026	}
1027	
1028	func attributionLineColumnWidth(lines []attributionLine) int {
1029		return max(len("Line"), len(strconv.Itoa(maxAttributionLineNumber(lines))))
1030	}
1031	
1032	func attributionTag(authorship attributionAuthorship) string {
1033		switch authorship {
1034		case attributionAI:
1035			return "[AI]"
1036		case attributionMixed:
1037			return "[MX]"
1038		case attributionUncommitted:
1039			return "[??]"
1040		case attributionHuman:
1041			return "[HU]"
1042		default:
1043			return "[HU]"
1044		}
1045	}
1046	
1047	// candidateFromContext projects the resolved checkpoint context onto a
1048	// per-line candidate. The two structs carry the same fields, so this is a
1049	// direct conversion — if they ever diverge, this stops compiling.
1050	func candidateFromContext(ctx attributionCheckpointContext) attributionCandidate {
1051		return attributionCandidate(ctx)
1052	}
1053	
1054	// applyPreferredToLine copies the preferred candidate's metadata onto the line.
1055	// It does not touch line.Authorship; callers decide how Mixed maps to authorship.
1056	func applyPreferredToLine(line *attributionLine, preferred *attributionCandidate) {
1057		if preferred == nil {
1058			return
1059		}
1060		line.CheckpointID = preferred.CheckpointID
1061		line.SessionID = preferred.SessionID
1062		line.Agent = preferred.Agent
1063		line.Model = preferred.Model
1064		line.Prompt = preferred.Prompt
1065		line.Intent = preferred.Intent
1066		line.MetadataMissing = preferred.MetadataMissing
1067	}
1068	
1069	func preferredAttributionCandidate(candidates []attributionCandidate, file string) *attributionCandidate {
1070		if len(candidates) == 0 {
1071			return nil
1072		}
1073		for i := range candidates {
1074			if pathsContainFile(candidates[i].FilesTouched, file) {
1075				return &candidates[i]
1076			}
1077		}
1078		return &candidates[0]
1079	}
1080	
1081	func pathsContainFile(paths []string, file string) bool {
1082		normalizedFile := normalizeGitPath(file)
1083		for _, p := range paths {
1084			if normalizeGitPath(p) == normalizedFile {
1085				return true
1086			}
1087		}
1088		return false
1089	}
1090	
1091	func normalizePathSlice(paths []string) []string {
1092		out := make([]string, 0, len(paths))
1093		for _, p := range paths {
1094			if normalized := normalizeGitPath(p); normalized != "" {
1095				out = appendUniqueString(out, normalized)
1096			}
1097		}
1098		return out
1099	}
1100	
1101	func normalizeGitPath(path string) string {
1102		path = strings.TrimSpace(path)
1103		path = strings.TrimPrefix(path, "/")
1104		return filepath.ToSlash(path)
1105	}
1106	
1107	func attributionIsMixed(attr *checkpoint.InitialAttribution) bool {
1108		if attr == nil {
1109			return false
1110		}
1111		agentChanged := attr.AgentLines+attr.AgentRemoved > 0
1112		humanChanged := attr.HumanAdded+attr.HumanModified+attr.HumanRemoved > 0
1113		return agentChanged && humanChanged
1114	}
1115	
1116	func shortCheckpointSession(line attributionLine) string {
1117		if line.CheckpointID == "" {
1118			return ""
1119		}
1120		if line.SessionID == "" {
1121			return line.CheckpointID
1122		}
1123		return line.CheckpointID + "/" + shortSessionID(line.SessionID)
1124	}
1125	
1126	func shortSessionID(sessionID string) string {
1127		if len(sessionID) <= 8 {
1128			return sessionID
1129		}
1130		return sessionID[:8]
1131	}
1132	
1133	func shortSHA(sha string) string {
1134		if len(sha) <= 8 {
1135			return sha
1136		}
1137		return sha[:8]
1138	}
1139	
1140	func shortAuthorName(author string) string {
1141		author = strings.TrimSpace(author)
1142		if before, _, ok := strings.Cut(author, "<"); ok {
1143			author = strings.TrimSpace(before)
1144		}
1145		return author
1146	}
1147	
1148	func fallbackString(value, fallback string) string {
1149		if strings.TrimSpace(value) == "" {
1150			return fallback
1151		}
1152		return value
1153	}
1154	
1155	func appendUniqueString(values []string, value string) []string {
1156		if value == "" {
1157			return values
1158		}
1159		for _, existing := range values {
1160			if existing == value {
1161				return values
1162			}
1163		}
1164		return append(values, value)
1165	}
1166	
1167	func isZeroCommit(sha string) bool {
1168		return sha == "" || strings.Trim(sha, "0") == ""
1169	}
1170	
1171	func writeJSON(w io.Writer, value any) error {
1172		encoder := json.NewEncoder(w)
1173		encoder.SetIndent("", "  ")
1174		if err := encoder.Encode(value); err != nil {
1175			return fmt.Errorf("encode json: %w", err)
1176		}
1177		return nil
1178	}
